export function ModelTestWorkspace({slug}:{slug:string}){
 const meta=MODELS.find(model=>model.slug===slug);
 const [prompt,setPrompt]=useState("اشرح مفهوم REST API مع مثال عملي.");
 const [instruction,setInstruction]=useState("أجب باللغة العربية وبأسلوب واضح.");
 const [sessionId,setSessionId]=useState("");
 const [busy,setBusy]=useState(false);
 const [result,setResult]=useState<{ok:boolean;ms:number;text:string;json:string}|null>(null);
 const [format,setFormat]=useState<"json"|"text">("text");
 if(!meta)return <><Heading eyebrow="MODEL TEST" title="النموذج غير موجود" desc="لا توجد صفحة اختبار لهذا النموذج."/><Link href="/models">العودة إلى النماذج</Link></>;
 const model=meta;
 async function run(){
  if(!prompt.trim()||busy)return;
  setBusy(true);setResult(null);const start=monotonicNow();
  try{
   const payload=model.slug==="gemini"?{prompt,instruction}:model.slug==="chatgpt"?{message:prompt,model:"default",...(sessionId?{sessionId}:{})}:{message:prompt,history:[]};
   const response=await fetch(model.endpoint,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});
   const data=await response.json();
   if(model.slug==="chatgpt"&&response.ok&&typeof data.sessionId==="string")setSessionId(data.sessionId);
   const textValue=model.slug==="chatgpt"?data.result?.message:data.response||data.output||data.error;
   setResult({ok:response.ok,ms:Math.round(monotonicNow()-start),text:String(textValue||"لا يوجد حقل نصي معروف في الاستجابة."),json:JSON.stringify(data,null,2)});
  }catch(error){
   const message=error instanceof Error?error.message:"تعذر الاتصال";
   setResult({ok:false,ms:Math.round(monotonicNow()-start),text:message,json:JSON.stringify({error:message},null,2)});
  }finally{setBusy(false)}
 }
 return <><Heading eyebrow={model.name.toUpperCase()+" · MODEL TEST"} title={"اختبار "+model.name} desc={"صفحة اختبار مخصصة لنموذج "+model.name+" فقط. لا يمكن تبديل النموذج من هذه الصفحة."}/><div className="ex-playground-grid ex-model-test"><Card><div className="ex-test-model-head"><span className="ex-status">نموذج ثابت</span><b>{model.name}</b><small>{model.provider}</small></div><label>المطالبة (Prompt)<textarea rows={7} value={prompt} onChange={event=>setPrompt(event.target.value)} placeholder="اكتب طلبك للنموذج"/></label>{model.slug==="gemini"&&<label>تعليمات إضافية<textarea rows={3} value={instruction} onChange={event=>setInstruction(event.target.value)} placeholder="تعليمات اختيارية للنموذج"/></label>}{model.slug==="chatgpt"&&<div className="ex-notice" role="note">{sessionId?"الجلسة مستمرة؛ الطلب التالي سيكمل المحادثة نفسها.":"سيتم إنشاء جلسة مشفرة عند أول طلب ناجح."} <button type="button" onClick={()=>setSessionId("")}>بدء جلسة جديدة</button></div>}<button className="ex-primary ex-run-test" disabled={busy||!prompt.trim()} onClick={run}>{busy?"جارٍ الاختبار…":model.slug==="chatgpt"&&sessionId?"إرسال ومتابعة ChatGPT":"تشغيل اختبار "+model.name}</button></Card><Card><div className="ex-card-head"><h3>نتيجة اختبار {model.name}</h3><div className="ex-toggle" role="group" aria-label="تنسيق النتيجة"><button className={format==="text"?"active":""} onClick={()=>setFormat("text")}>Text</button><button className={format==="json"?"active":""} onClick={()=>setFormat("json")}>JSON</button></div></div>{result?<><div className="ex-test-result-meta"><span className={result.ok?"ex-good":"ex-bad"}>{result.ok?"نجح الاختبار":"فشل الاختبار"}</span><span>{result.ms} ms</span></div><pre className="ex-test-output">{format==="json"?result.json:result.text}</pre></>:<div className="ex-test-empty"><span>—</span><p>لم يتم تشغيل اختبار لهذا النموذج بعد.</p></div>}</Card></div><div className="ex-test-back"><Link href={"/models/"+model.slug}>العودة إلى تفاصيل {model.name}</Link><Link href="/models">كل النماذج</Link></div></>;
}

